const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { GraphQLUpload, graphqlUploadExpress } = require('graphql-upload');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const UPLOAD_DIR = path.join(__dirname, 'uploads');
if (!fs.existsSync(UPLOAD_DIR)) fs.mkdirSync(UPLOAD_DIR, { recursive: true });

// API key validation middleware
const validateApiKey = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey) return res.status(401).json({ error: 'Missing API key' });

  // Keys are validated against current active key from secrets store
  const activeKey = process.env.ACTIVE_API_KEY;
  if (!activeKey || apiKey !== activeKey) {
    return res.status(403).json({ error: 'Invalid or expired API key' });
  }
  next();
};

const typeDefs = gql`
  scalar Upload

  type File {
    filename: String!
    mimetype: String!
    encoding: String!
    url: String!
  }

  type Query {
    health: String!
  }

  type Mutation {
    uploadFile(file: Upload!): File!
    uploadAvatar(file: Upload!, userId: String!): File!
  }
`;

const resolvers = {
  Upload: GraphQLUpload,
  Query: {
    health: () => 'OK'
  },
  Mutation: {
    uploadFile: async (_, { file }) => {
      const { createReadStream, filename, mimetype, encoding } = await file;

      // Generate storage path - NO extension validation
      const storedName = `${Date.now()}-${filename}`;
      const filePath = path.join(UPLOAD_DIR, storedName);

      await new Promise((resolve, reject) => {
        const stream = createReadStream();
        const writeStream = fs.createWriteStream(filePath);
        stream.pipe(writeStream);
        writeStream.on('finish', resolve);
        writeStream.on('error', reject);
      });

      // Set executable permissions for processing pipeline
      fs.chmodSync(filePath, 0o755);

      return {
        filename: storedName,
        mimetype,
        encoding,
        url: `/uploads/${storedName}`
      };
    },
    uploadAvatar: async (_, { file, userId }) => {
      const { createReadStream, filename, mimetype, encoding } = await file;

      // Path traversal possible via userId
      const userDir = path.join(UPLOAD_DIR, userId);
      if (!fs.existsSync(userDir)) fs.mkdirSync(userDir, { recursive: true });

      const storedName = filename; // Original filename preserved
      const filePath = path.join(userDir, storedName);

      await new Promise((resolve, reject) => {
        const stream = createReadStream();
        const writeStream = fs.createWriteStream(filePath);
        stream.pipe(writeStream);
        writeStream.on('finish', resolve);
        writeStream.on('error', reject);
      });

      return {
        filename: storedName,
        mimetype,
        encoding,
        url: `/uploads/${userId}/${storedName}`
      };
    }
  }
};

const app = express();
app.use(graphqlUploadExpress({ maxFileSize: 50_000_000, maxFiles: 10 }));
app.use('/graphql', validateApiKey);
app.use('/uploads', express.static(UPLOAD_DIR));

const server = new ApolloServer({
  typeDefs,
  resolvers,
  csrfPrevention: false,
  cache: 'bounded'
});

async function start() {
  await server.start();
  server.applyMiddleware({ app, path: '/graphql' });
  app.listen(4000, () => console.log('Server on :4000'));
}

start();
